import * as React from "react";

export type InfoCircleIconProps = React.SVGProps<SVGSVGElement> & { size?: number };

export function InfoCircleIcon({ size = 20, ...props }: InfoCircleIconProps) {
  return (
    <svg
      width={size}
      height={size}
      viewBox="0 0 24 24"
      fill="none"
      stroke="currentColor"
      strokeWidth="1.8"
      strokeLinecap="round"
      strokeLinejoin="round"
      aria-hidden="true"
      {...props}
    >
      <circle cx="12" cy="12" r="8.5"/><path d="M12 11v5"/><circle cx="12" cy="8" r="1.2"/>
    </svg>
  );
}
